use system.os
use system.fs
use system.gpu
use system.collections.array
use system.collections.list

// One thread per grid point: the escape-time loop runs on the GPU.
gpu fn escape_times(width int, total int, limit int, x_min f32, x_step f32, y_min f32, y_step f32, dst out Array<int, 1048576>)
    let i = kernel.global_idx.x
    if i < total
        let cx = x_min + ((i % width) as f32 + 0.5) * x_step
        let cy = y_min + ((i / width) as f32 + 0.5) * y_step
        var zx = 0.0 as f32
        var zy = 0.0 as f32
        var n = 0
        while n < limit and zx * zx + zy * zy <= 4.0
            let next_zx = zx * zx - zy * zy + cx
            zy = 2.0 * zx * zy + cy
            zx = next_zx
            n = n + 1
        dst[i] = n

fn parse_int(text String) int
    match text.to_int()
        Some(v): v
        None: panic(f"not an integer: {text}")

fn parse_float(text String) float
    match text.to_float()
        Some(v): v
        None: panic(f"not a number: {text}")

// Splits the whole file on any whitespace, so the line layout does not matter.
fn read_tokens(path String) List<String>
    let fs = Fs()
    let text = match fs.read_file(path)
        Result.Ok(v): v
        Result.Err: panic(f"cannot read {path}")
    let spaced = text.replace("\r", " ").replace("\n", " ").replace("\t", " ")
    var tokens = List<String>()
    for part in spaced.split(" ")
        if part.length() > 0: tokens.push(part)
    tokens

// Formats thousandths as "whole.fff", padding the fraction to three digits.
fn format_milli(milli int) String
    let frac = milli % 1000
    let frac_text = f"{frac + 1000}".substring(1, 4)
    f"{milli / 1000}.{frac_text}"

fn main()
    let tokens = read_tokens(Args().element_at(0))
    let width = parse_int(tokens.element_at(0))
    let height = parse_int(tokens.element_at(1))
    let limit = parse_int(tokens.element_at(2))
    let x_min = parse_float(tokens.element_at(3))
    let x_max = parse_float(tokens.element_at(4))
    let y_min = parse_float(tokens.element_at(5))
    let y_max = parse_float(tokens.element_at(6))

    let total = width * height
    let x_step = (x_max - x_min) / (width as float)
    let y_step = (y_max - y_min) / (height as float)
    let groups = (total + 255) / 256

    gpu var escapes = Array<int, 1048576>()
    escape_times(width, total, limit, x_min as f32, x_step as f32, y_min as f32, y_step as f32, escapes).launch(Dim3(groups, 1, 1), Dim3(256, 1, 1))
    var host = Array<int, 1048576>()
    host = escapes

    var inside = 0
    var escaped = 0
    var escaped_sum = 0
    var bins = Array<int, 8>()
    for i in 0..total
        let n = host.element_at(i)
        if n == limit
            inside = inside + 1
        else
            escaped = escaped + 1
            escaped_sum = escaped_sum + n
            let bin = (8 * n) / limit
            bins.set(bin, bins.element_at(bin) + 1)

    // Mean rounded half-up to thousandths, in integers: round(1000 * sum / escaped).
    var milli = 0
    if escaped > 0
        milli = (2000 * escaped_sum + escaped) / (2 * escaped)

    println(f"INSIDE {inside}")
    for b in 0..8
        println(f"BIN {b} {bins.element_at(b)}")
    println(f"MEAN {format_milli(milli)}")

